# forestdb-2025-problang-adjectives-qud/atom-1
# RSA model with QUD uncertainty and vague adjectives
# Returns: posterior distribution over {price, valence} for pragmatic listener hearing "expensive"

import json
import math
import functools
import torch
import pyro
import pyro.distributions as dist
from pyro.infer import Importance
from collections import defaultdict

prices = [50, 500, 1000, 5000, 10000]
price_probs_raw = [0.8070, 0.1070, 0.0434, 0.0223, 0.0203]
price_probs_t = torch.tensor(price_probs_raw)
valence_probs_by_price = {50: 0.3173, 500: 0.7920, 1000: 0.8933, 5000: 0.9524, 10000: 0.9864}
utterances = ["expensive", "notExpensive"]
costs = {"expensive": 0.0, "notExpensive": 1.0}
alpha = 1.0
quds = ["price", "valence", "priceValence"]

def meaning(utterance, price, theta):
    if utterance == "expensive": return price >= theta
    elif utterance == "notExpensive": return price <= theta
    return True

def qud_fn(qud, price, valence):
    if qud == "price": return ("price", price)
    elif qud == "valence": return ("valence", valence)
    else: return ("priceValence", price, valence)

@functools.lru_cache(maxsize=None)
def literal_listener(utterance, qud, theta):
    totals = {}
    denom = 0.0
    for p in prices:
        if not meaning(utterance, p, theta): continue
        for v in [True, False]:
            pv = valence_probs_by_price[p] if v else (1 - valence_probs_by_price[p])
            w = (1.0 / len(prices)) * pv
            qa = qud_fn(qud, p, v)
            totals[qa] = totals.get(qa, 0.0) + w
            denom += w
    if denom == 0: return {}
    return {k: vv/denom for k, vv in totals.items()}

@functools.lru_cache(maxsize=None)
def speaker_log_prob_expensive(price, valence, qud, theta):
    qa = qud_fn(qud, price, valence)
    log_scores = []
    for utt in utterances:
        ll = literal_listener(utt, qud, theta)
        p_qa = ll.get(qa, 0.0)
        log_scores.append(alpha * (math.log(p_qa + 1e-300) - costs[utt]))
    max_s = max(log_scores)
    log_norm = max_s + math.log(sum(math.exp(s - max_s) for s in log_scores))
    return log_scores[0] - log_norm  # "expensive" is index 0

@functools.lru_cache(maxsize=None)
def marginal_speaker_log_prob(price, valence):
    total = 0.0
    for qud in quds:
        for theta in prices:
            total += (1.0/3.0) * (1.0/5.0) * math.exp(speaker_log_prob_expensive(price, valence, qud, theta))
    return math.log(total + 1e-300)

def model():
    price_idx = pyro.sample("price_idx", dist.Categorical(price_probs_t))
    price = prices[price_idx.item()]
    vp = valence_probs_by_price[price]
    valence_s = pyro.sample("valence", dist.Bernoulli(vp))
    valence = bool(valence_s.item())
    log_p = marginal_speaker_log_prob(price, valence)
    pyro.factor("obs", torch.tensor(log_p))
    return price_idx

importance = Importance(model, num_samples=60000)
importance.run()

log_weights_t = torch.tensor(importance.log_weights)
weights = torch.softmax(log_weights_t, dim=0)

agg = defaultdict(float)
for trace, w in zip(importance.exec_traces, weights):
    p_idx = int(trace.nodes["price_idx"]["value"].item())
    v = bool(trace.nodes["valence"]["value"].item())
    price = prices[p_idx]
    key = json.dumps({"price": price, "valence": v}, sort_keys=True)
    agg[key] += w.item()

total = sum(agg.values())
ANSWER = {k: v/total for k, v in agg.items()}

import math, json as _json
from collections import defaultdict

states = [1, 2, 3, 4]
utterances = ["", "dumb as rocks", "dumb", "f*cking idiot"]
goals = ["goalState", "goalValence", "goalArousal"]
alpha = 10
lam = -1.25

literal_sem = {
    "": [0.25, 0.25, 0.25, 0.25],
    "dumb as rocks": [0.45, 0.85, 0.20, 0.02],
    "dumb": [0.85, 0.95, 0.02, 0.02],
    "f*cking idiot": [0.95, 0.55, 0.02, 0.02],
}
valence_probs = {1: 0.01, 2: 0.33, 3: 0.66, 4: 0.99}
arousal_probs = {1: 0.1, 2: 0.7, 3: 0.7, 4: 0.1}
phi_vals = [round(0.05 * i, 2) for i in range(1, 19)]
n_phi = len(phi_vals)

def goal_fn(goal, state, valence, arousal):
    if goal == "goalState": return state
    if goal == "goalValence": return valence
    return arousal

def value_fn(s): return lam * s

def compute_L0(utt, goal):
    joint = defaultdict(float)
    for s in states:
        p_meaning = literal_sem[utt][s-1]
        if p_meaning == 0: continue
        for valence, p_val in [("good", valence_probs[s]), ("bad", 1-valence_probs[s])]:
            for arousal, p_ar in [("low", arousal_probs[s]), ("high", 1-arousal_probs[s])]:
                qud_ans = str(goal_fn(goal, s, valence, arousal))
                joint[(qud_ans, s)] += 0.25 * p_meaning * p_val * p_ar
    total = sum(joint.values())
    return {k: v/total for k, v in joint.items()} if total > 0 else {}

L0_cache = {}
def get_L0(utt, goal):
    k = (utt, goal)
    if k not in L0_cache: L0_cache[k] = compute_L0(utt, goal)
    return L0_cache[k]

def L0_qud_marginal(utt, goal):
    l0 = get_L0(utt, goal)
    m = defaultdict(float)
    for (q, s), p in l0.items(): m[q] += p
    return dict(m)

def L0_state_marginal(utt, goal):
    l0 = get_L0(utt, goal)
    m = defaultdict(float)
    for (q, s), p in l0.items(): m[s] += p
    return dict(m)

S1_cache = {}
def compute_S1(state, phi, goal, valence, arousal):
    k = (state, phi, goal, valence, arousal)
    if k in S1_cache: return S1_cache[k]
    qud_ans = str(goal_fn(goal, state, valence, arousal))
    utt_ws = []
    for utt in utterances:
        l0_qud = L0_qud_marginal(utt, goal)
        l0_state = L0_state_marginal(utt, goal)
        p_qud = l0_qud.get(qud_ans, 0.0)
        ep = math.log(p_qud) if p_qud > 0 else -1e10
        ant = sum(l0_state.get(s, 0.0) * value_fn(s) for s in states)
        util = phi * ep + (1-phi) * ant
        utt_ws.append(math.exp(alpha * util))
    total = sum(utt_ws)
    result = {utt: w/total for utt, w in zip(utterances, utt_ws)}
    S1_cache[k] = result
    return result

for state in states:
    for phi in phi_vals:
        for goal in goals:
            for valence in ["good", "bad"]:
                for arousal in ["low", "high"]:
                    compute_S1(state, phi, goal, valence, arousal)

spk_table = {}
for si, state in enumerate(states):
    for pi, phi in enumerate(phi_vals):
        for gi, goal in enumerate(goals):
            for vi, valence in enumerate(["good", "bad"]):
                for ai, arousal in enumerate(["low", "high"]):
                    s1 = compute_S1(state, phi, goal, valence, arousal)
                    lps = [math.log(s1[utt]) if s1[utt] > 0 else -1e38 for utt in utterances]
                    spk_table[(si, pi, gi, vi, ai)] = lps

obs_utt_idx = utterances.index("dumb as rocks")
state_probs_t = torch.ones(len(states)) / len(states)
phi_probs_t = torch.ones(n_phi) / n_phi
goal_probs_t = torch.ones(3) / 3.0

def pragma_model():
    s_idx = pyro.sample("state", dist.Categorical(state_probs_t))
    si = s_idx.item()
    state = states[si]
    vn_p = valence_probs[state]
    val_bit = pyro.sample("valence", dist.Bernoulli(torch.tensor(vn_p)))
    # valencePrior: P(good) = valence_probs[state]; Bernoulli(vn_p)=1 means good
    vi = 1 if val_bit.item() < 0.5 else 0  # vi=0:good, vi=1:bad
    ar_p = arousal_probs[state]
    ar_bit = pyro.sample("arousal", dist.Bernoulli(torch.tensor(ar_p)))
    # arousalPrior: P(low) = arousal_probs[state]; Bernoulli(ar_p)=1 means low
    ai = 0 if ar_bit.item() > 0.5 else 1  # ai=0:low, ai=1:high
    phi_idx = pyro.sample("phi", dist.Categorical(phi_probs_t))
    pi = phi_idx.item()
    goal_idx = pyro.sample("goal", dist.Categorical(goal_probs_t))
    gi = goal_idx.item()
    lps = spk_table[(si, pi, gi, vi, ai)]
    pyro.factor("obs", torch.tensor(lps[obs_utt_idx]))
    return s_idx

post = pyro.infer.Importance(pragma_model, num_samples=60000).run()
agg = defaultdict(float)
lw = torch.stack(post.log_weights)
weights = torch.softmax(lw, dim=0)
for trace, w in zip(post.exec_traces, weights):
    si = int(trace.nodes["state"]["value"].item())
    state = states[si]
    agg[state] += w.item()

total = sum(agg.values())
ANSWER = {state: agg.get(state, 0.0)/total for state in states}

import math, json as _json
from collections import defaultdict

binParam = 3
sup_mu, sup_sigma = 0.0, 1.0
sub_mu, sub_sigma = 1.0, 0.5

step = sup_sigma / binParam
stateVals = []
v = sup_mu - 3 * sup_sigma
while v < sup_mu + 3 * sup_sigma - 1e-10:
    stateVals.append(round(v, 10))
    v += step
n_states = len(stateVals)

def gaussian_pdf(x, mu, sigma):
    return math.exp(-0.5 * ((x - mu) / sigma) ** 2) / (sigma * math.sqrt(2 * math.pi))

def state_probs(mu, sigma):
    ps = [gaussian_pdf(s, mu, sigma) for s in stateVals]
    total = sum(ps)
    return torch.tensor([p/total for p in ps])

sub_state_probs = state_probs(sub_mu, sub_sigma)
tall_thresholds = [s - 1.0/(binParam*2) for s in sorted(stateVals)]
short_thresholds = [s + 1.0/(binParam*2) for s in sorted(stateVals)]
n_thresh = len(tall_thresholds)
utterances = ["tall", "short", "silence"]
alpha = 5.0
classes = ["subordinate", "superordinate"]

def meaning(utt, state, tall_t, short_t):
    if utt == "tall": return state > tall_t
    if utt == "short": return state < short_t
    return True

ll_probs = {}
for utt in utterances:
    ll_probs[utt] = {}
    for ci, (cmu, csigma) in enumerate([(sub_mu, sub_sigma), (sup_mu, sup_sigma)]):
        sp = state_probs(cmu, csigma)
        ll_probs[utt][ci] = {}
        for ti, tall_t in enumerate(tall_thresholds):
            ll_probs[utt][ci][ti] = {}
            for shi, short_t in enumerate(short_thresholds):
                weights = [sp[si].item() if meaning(utt, sv, tall_t, short_t) else 0.0
                           for si, sv in enumerate(stateVals)]
                total = sum(weights)
                ll_probs[utt][ci][ti][shi] = [w/total for w in weights] if total > 0 else None

spk1_log_p = {}
for si in range(n_states):
    spk1_log_p[si] = {}
    for ci in range(2):
        spk1_log_p[si][ci] = {}
        for ti in range(n_thresh):
            spk1_log_p[si][ci][ti] = {}
            for shi in range(n_thresh):
                log_ws = []
                for ui, utt in enumerate(utterances):
                    ll_p = ll_probs[utt][ci][ti][shi]
                    if ll_p is None:
                        log_ws.append(float("-inf"))
                    else:
                        p_state = ll_p[si]
                        log_ws.append(alpha * (math.log(p_state) if p_state > 0 else float("-inf")))
                finite_vals = [x for x in log_ws if x != float("-inf")]
                if not finite_vals:
                    spk1_log_p[si][ci][ti][shi] = [float("-inf")] * 3
                    continue
                max_w = max(finite_vals)
                exps = [math.exp(x - max_w) if x != float("-inf") else 0.0 for x in log_ws]
                total = sum(exps)
                spk1_log_p[si][ci][ti][shi] = [
                    math.log(e/total) if e > 0 else float("-inf") for e in exps]

obs_utt_idx = 0  # "tall"

def pragma_model():
    s_idx = pyro.sample("state", dist.Categorical(sub_state_probs))
    tall_idx = pyro.sample("tall_t", dist.Categorical(torch.ones(n_thresh)))
    short_idx = pyro.sample("short_t", dist.Categorical(torch.ones(n_thresh)))
    comp_idx = pyro.sample("comp", dist.Categorical(torch.ones(2)))
    ci = comp_idx.item()
    si = s_idx.item()
    ti = tall_idx.item()
    shi = short_idx.item()
    lps = spk1_log_p[si][ci][ti][shi]
    lp_obs = lps[obs_utt_idx]
    if lp_obs == float("-inf"):
        pyro.factor("obs", torch.tensor(-1e38))
    else:
        pyro.factor("obs", torch.tensor(lp_obs))
    return comp_idx

post = pyro.infer.Importance(pragma_model, num_samples=50000).run()
agg = defaultdict(float)
lw = torch.stack(post.log_weights)
weights = torch.softmax(lw, dim=0)
for trace, w in zip(post.exec_traces, weights):
    ci = int(trace.nodes["comp"]["value"].item())
    agg[classes[ci]] += w.item()

total = sum(agg.values())
ANSWER = {_json.dumps(cls): agg.get(cls, 0.0)/total for cls in classes}

import math as _math
import json as _json

objects = ["blue square", "blue circle", "green square"]
utterances = ["blue", "green", "square", "circle", "blue square", "blue circle", "green square"]
cost_params = [0.05 + 0.5 * i for i in range(10)]
alpha = 1.0

def meaning(utt, obj):
    return utt in obj

def cost(utt, cp):
    return cp * len(utt.split())

def lit_listener(utt):
    applicable = [o for o in objects if meaning(utt, o)]
    n = len(applicable)
    if n == 0:
        return {o: 0.0 for o in objects}
    return {o: (1.0/n if o in applicable else 0.0) for o in objects}

ll_cache = {u: lit_listener(u) for u in utterances}

def speaker_logprobs(obj, cp):
    lps = []
    for u in utterances:
        ll_p = ll_cache[u].get(obj, 0.0)
        lps.append(alpha * (_math.log(max(ll_p, 1e-300)) - cost(u, cp)))
    max_lp = max(lps)
    exps = [_math.exp(lp - max_lp) for lp in lps]
    total = sum(exps)
    return [e/total for e in exps]

sp_cache = {}
for o in objects:
    for cp in cost_params:
        sp_cache[(o, cp)] = speaker_logprobs(o, cp)

utt_to_idx = {u: i for i, u in enumerate(utterances)}
obj_prior_t = torch.ones(3) / 3
cp_prior_t = torch.ones(10) / 10

def pragmatic_listener_model():
    obj_idx = pyro.sample("obj", dist.Categorical(obj_prior_t))
    obj = objects[obj_idx.item()]
    cp_idx = pyro.sample("cp", dist.Categorical(cp_prior_t))
    cp = cost_params[cp_idx.item()]
    sp = sp_cache[(obj, cp)]
    obs_idx = utt_to_idx["blue"]
    pyro.factor("obs", torch.tensor(_math.log(max(sp[obs_idx], 1e-300))))

importance = pyro.infer.Importance(pragmatic_listener_model, num_samples=30000)
importance.run()

weights = torch.softmax(torch.tensor(importance.log_weights), dim=0)
traces = importance.exec_traces

from collections import defaultdict
agg = defaultdict(float)
for tr, w in zip(traces, weights):
    oi = tr.nodes["obj"]["value"].item()
    ci = tr.nodes["cp"]["value"].item()
    key = _json.dumps({"costParameter": cost_params[ci], "obj": objects[oi]}, sort_keys=True)
    agg[key] += w.item()

total = sum(agg.values())
ANSWER = {k: v/total for k, v in agg.items()}

import json
import math as _math

numHorses = 2
states = [0, 1, 2]
baserate = 0.5
state_prior = torch.tensor([0.25, 0.5, 0.25])
utterances = ["null", "every-not"]
cost = 1.0
scopes = ["surface", "inverse"]
QUDs = ["how many?", "all red?", "none red?"]
alpha = 1.0

def meaning(utterance, state, scope):
    if utterance == "every-not":
        if scope == "surface":
            return state == 0
        else:
            return state < numHorses
    else:
        return True

def qud_fn(qud, state):
    if qud == "all red?": return state == numHorses
    if qud == "none red?": return state == 0
    return state

def lit_listener(utterance, scope, qud):
    weights = {}
    for s in states:
        if meaning(utterance, s, scope):
            qval = qud_fn(qud, s)
            key = str(qval)
            weights[key] = weights.get(key, 0.0) + 1.0/3
    total = sum(weights.values())
    return {k: v/total for k, v in weights.items()} if total > 0 else {}

ll_cache = {}
for u in utterances:
    for sc in scopes:
        for qud in QUDs:
            ll_cache[(u, sc, qud)] = lit_listener(u, sc, qud)

def s1_probs(scope, state, qud):
    qval = str(qud_fn(qud, state))
    lps = []
    for u in utterances:
        ll = ll_cache[(u, scope, qud)]
        p = ll.get(qval, 0.0)
        lps.append(alpha * (_math.log(max(p, 1e-300)) - cost))
    max_lp = max(lps)
    exps = [_math.exp(lp - max_lp) for lp in lps]
    total = sum(exps)
    return [e/total for e in exps]

s1_cache = {}
for sc in scopes:
    for st in states:
        for qud in QUDs:
            s1_cache[(sc, st, qud)] = s1_probs(sc, st, qud)

def l1_probs(utterance):
    u_idx = utterances.index(utterance)
    state_weights = {}
    for i, st in enumerate(states):
        for sc in scopes:
            for qud in QUDs:
                w = state_prior[i].item() * 0.5 * (1.0/3)
                sp = s1_cache[(sc, st, qud)][u_idx]
                state_weights[st] = state_weights.get(st, 0.0) + w * sp
    total = sum(state_weights.values())
    return {k: v/total for k, v in state_weights.items()}

l1_cache = {u: l1_probs(u) for u in utterances}

def s2_model():
    utt_idx = pyro.sample("utterance", dist.Categorical(torch.ones(len(utterances))/len(utterances)))
    utt = utterances[utt_idx.item()]
    l1 = l1_cache[utt]
    log_p = _math.log(max(l1.get(1, 0.0), 1e-300))
    pyro.factor("obs", torch.tensor(log_p))

importance = pyro.infer.Importance(s2_model, num_samples=20000)
importance.run()

weights = torch.softmax(torch.tensor(importance.log_weights), dim=0)
traces = importance.exec_traces

from collections import defaultdict
utt_agg = defaultdict(float)
for tr, w in zip(traces, weights):
    u_idx = tr.nodes["utterance"]["value"].item()
    utt_agg[utterances[u_idx]] += w.item()

total = sum(utt_agg.values())
# json.dumps-encoded keys so the string label "null" round-trips as a string
