import pyro.infer
from collections import defaultdict

states = ["terrible", "ok", "amazing"]
arousals = ["low", "high"]
goals = ["goalState", "goalValence", "goalArousal"]
utterances = states

state_weights = torch.tensor([1.0, 50.0, 50.0])
state_probs = state_weights / state_weights.sum()

def valence_neg_prob(state):
    if state == "terrible": return 0.99
    if state == "ok": return 0.5
    return 0.01

def arousal_probs_for_state(state):
    if state == "terrible": return torch.tensor([0.1, 0.9])
    if state == "ok": return torch.tensor([0.9, 0.1])
    return torch.tensor([0.1, 0.9])

def goal_state_fn(goal, state, valence, arousal):
    if goal == "goalState": return str(state)
    if goal == "goalValence": return str(valence)
    return str(arousal)

def literal_listener_dist(utterance, goal):
    total = {}
    for si, s in enumerate(states):
        if s != utterance:
            continue
        sp = state_probs[si].item()
        for vi, val in enumerate([-1, 1]):
            vp = valence_neg_prob(s) if val == -1 else (1 - valence_neg_prob(s))
            a_probs = arousal_probs_for_state(s)
            for ai, ar in enumerate(arousals):
                ap = a_probs[ai].item()
                gval = goal_state_fn(goal, s, val, ar)
                total[gval] = total.get(gval, 0) + sp * vp * ap
    tot = sum(total.values())
    return {k: v/tot for k, v in total.items()}

def speaker_log_probs(state, valence, arousal, goal):
    log_probs = []
    for utt in utterances:
        ll_dist = literal_listener_dist(utt, goal)
        gval = goal_state_fn(goal, state, valence, arousal)
        p = ll_dist.get(gval, 0.0)
        log_probs.append(torch.log(torch.tensor(p + 1e-30)))
    return torch.stack(log_probs)

# Precompute speaker distributions
speaker_cache = {}
for si, s in enumerate(states):
    for vi, val in enumerate([-1, 1]):
        for ai, ar in enumerate(arousals):
            for gi, goal in enumerate(goals):
                lp = speaker_log_probs(s, val, ar, goal)
                speaker_cache[(si, vi, ai, gi)] = torch.log_softmax(lp, 0)

# Pragmatic listener model using pyro Importance sampling
def pragmatic_model():
    si = pyro.sample("state_idx", dist.Categorical(state_probs))
    s = states[si.item()]

    vnp = valence_neg_prob(s)
    vi = pyro.sample("valence_idx", dist.Bernoulli(1.0 - vnp))  # 0->neg, 1->pos
    val = 1 if vi.item() == 1 else -1
    vi_int = 0 if val == -1 else 1

    a_probs = arousal_probs_for_state(s)
    ai = pyro.sample("arousal_idx", dist.Categorical(a_probs))
    ar = arousals[ai.item()]

    gi = pyro.sample("goal_idx", dist.Categorical(torch.ones(3)/3))
    goal = goals[gi.item()]

    # Observe utterance="terrible" (index 0) via speaker
    sp_lp = speaker_cache[(si.item(), vi_int, ai.item(), gi.item())]
    pyro.factor("speaker_obs", sp_lp[0])  # terrible is index 0

    return (si.item(), vi_int, ai.item(), gi.item())

importance = pyro.infer.Importance(pragmatic_model, num_samples=50000)
