import math as _math

states = [0, 1, 2, 3]
utterances = ["all", "some", "none"]
alpha = 1.0

def literal_meaning(utt, state):
    if utt == "all": return state == 3
    if utt == "some": return state > 0
    return state == 0

def qud_fn(qud, state):
    if qud == "all?": return state == 3
    return state > 0

def build_lit_listener():
    result = {}
    for utt in utterances:
        for qud in ["all?", "any?"]:
            weights = {True: 0.0, False: 0.0}
            for s in states:
                if literal_meaning(utt, s):
                    weights[qud_fn(qud, s)] += 0.25
            total = sum(weights.values())
            if total > 0:
                result[(utt, qud)] = {k: v/total for k, v in weights.items()}
            else:
                result[(utt, qud)] = {True: 0.5, False: 0.5}
    return result

ll_table = build_lit_listener()

def speaker_logprobs(state, qud):
    qval = qud_fn(qud, state)
    raw_lps = []
    for utt in utterances:
        p = ll_table[(utt, qud)].get(qval, 0.0)
        raw_lps.append(alpha * _math.log(max(p, 1e-300)))
    max_lp = max(raw_lps)
    exp_lps = [_math.exp(lp - max_lp) for lp in raw_lps]
    total = sum(exp_lps)
    return [e/total for e in exp_lps]

sp_table = {}
for s in states:
    for qud in ["all?", "any?"]:
        sp_table[(s, qud)] = speaker_logprobs(s, qud)

utt_to_idx = {u: i for i, u in enumerate(utterances)}

def pragmatic_listener_model():
    state_idx = pyro.sample("state", dist.Categorical(torch.ones(4)/4))
    state = states[state_idx.item()]
    qud = "any?"
    sp = sp_table[(state, qud)]
    obs_idx = utt_to_idx["some"]
    pyro.factor("obs", torch.tensor(_math.log(max(sp[obs_idx], 1e-300))))
    return state_idx

importance = pyro.infer.Importance(pragmatic_listener_model, num_samples=20000)
importance.run()

