import pyro.infer

def geometric(depth=0, max_depth=50):
    # flip() equivalent: Bernoulli(0.5)
    flip = pyro.sample(f"flip_{depth}", dist.Bernoulli(0.5))
    if flip.item() == 1.0:
        return torch.tensor(0)
    else:
        if depth >= max_depth:
            return torch.tensor(0)  # truncate recursion
        return torch.tensor(1) + geometric(depth + 1, max_depth)

def model():
    return geometric()

imp = pyro.infer.Importance(model, num_samples=10000)
