import math, json as _json
from collections import defaultdict

maxNumber = 20

def filter_in_range(lst):
    return sorted(set(v for v in lst if 1 <= v <= maxNumber))

def gen_evens():
    return filter_in_range(range(2, maxNumber + 1, 2))

def gen_odds():
    return filter_in_range(range(1, maxNumber + 1, 2))

def gen_multiples(base):
    return filter_in_range(base * v for v in range(1, maxNumber + 1))

def gen_powers(base):
    result, seen, exp = [], set(), 0
    while True:
        v = base ** exp
        if v in seen: break
        seen.add(v)
        if v > maxNumber: break
        result.append(v)
        exp += 1
    return filter_in_range(result)

def get_set(rule):
    parts = rule.split("_")
    if parts[0] == "multiples": return set(gen_multiples(int(parts[2])))
    elif parts[0] == "powers": return set(gen_powers(int(parts[2])))
    elif rule == "evens": return set(gen_evens())
    elif rule == "odds": return set(gen_odds())
    elif parts[0] == "interval": return set(range(int(parts[1]), int(parts[2])+1))
    raise ValueError(rule)

rule_hyps = ([f"multiples_of_{b}" for b in range(1,12)] +
             [f"powers_of_{b}" for b in range(1,12)] + ["evens", "odds"])
interval_hyps = [f"interval_{a}_{b}"
                 for a in range(1, maxNumber) for b in range(a+1, maxNumber+1)]
n_rules = len(rule_hyps)
n_intervals = len(interval_hyps)

examples = [3, 10]
test_query = 12

def model():
    use_rule = pyro.sample("use_rule", dist.Bernoulli(0.5))
    if use_rule.item() > 0.5:
        hyp_idx = pyro.sample("hyp", dist.Categorical(torch.ones(n_rules)))
        hyp = rule_hyps[hyp_idx.item()]
    else:
        hyp_idx = pyro.sample("hyp", dist.Categorical(torch.ones(n_intervals)))
        hyp = interval_hyps[hyp_idx.item()]
    s = get_set(hyp)
    log_lh = sum(math.log(1/len(s)) if ex in s else -1e38 for ex in examples)
    pyro.factor("lh", torch.tensor(log_lh))
    tqr = test_query in s
    return hyp, tqr

post = pyro.infer.Importance(model, num_samples=60000).run()
