    hyp_idx = trace.nodes["hyp"]["value"].item()
    hyp = rule_hyps[int(hyp_idx)] if use_rule else interval_hyps[int(hyp_idx)]
    s = get_set(hyp)
    tqr = test_query in s
    agg[(hyp, tqr)] += w.item()

total = sum(agg.values())
