# probmods2-occams-razor/ex1.3: Concept learning via Pyro
# Exact computation matching WebPPL enumerate - pure Python arithmetic

import math

maxNumber = 20

def gen_evens():
    return [v for v in range(1, maxNumber + 1) if v % 2 == 0]

def gen_odds():
    return [v for v in range(1, maxNumber + 1) if (v + 1) % 2 == 0]

def gen_multiples(base):
    return [base * v for v in range(1, maxNumber + 1) if 1 <= base * v <= maxNumber]

def gen_powers(base):
    result = []
    for exp in range(maxNumber):
        val = base ** exp
        if val > maxNumber:
            break
        if 1 <= val <= maxNumber:
            result.append(val)
    return list(set(result))

rule_hypotheses = ([f'multiples_of_{n}' for n in range(1, 12)] +
                   [f'powers_of_{n}' for n in range(1, 12)] +
                   ['evens', 'odds'])
interval_hypotheses = [f'interval_{a}_{b}'
                       for a in range(1, maxNumber + 1)
                       for b in range(a + 1, maxNumber + 1)]

def get_set(h):
    parts = h.split('_')
    if parts[0] == 'multiples':
        return gen_multiples(int(parts[2]))
    elif parts[0] == 'powers':
        return gen_powers(int(parts[2]))
    elif parts[0] == 'evens':
        return gen_evens()
    elif parts[0] == 'odds':
        return gen_odds()
    elif parts[0] == 'interval':
        return list(range(int(parts[1]), int(parts[2]) + 1))

rule_sets = [get_set(h) for h in rule_hypotheses]
interval_sets = [get_set(h) for h in interval_hypotheses]

all_hyp_sets = rule_sets + interval_sets
n_rules = len(rule_hypotheses)
n_intervals = len(interval_hypotheses)
n_total = n_rules + n_intervals

# Log prior (50/50 mix)
log_prior = (
    [math.log(0.5 / n_rules)] * n_rules +
    [math.log(0.5 / n_intervals)] * n_intervals
)

examples = [3, 6, 9]

def log_likelihood(h_set):
    if not h_set:
        return -math.inf
    for e in examples:
        if e not in h_set:
            return -math.inf
    return -len(examples) * math.log(len(h_set))

# Compute unnormalized log posteriors in pure Python
log_posteriors = [log_prior[i] + log_likelihood(all_hyp_sets[i]) for i in range(n_total)]

# Normalize using log-sum-exp (pure Python, maximum precision)
finite_lps = [lp for lp in log_posteriors if lp > -1e10]
if not finite_lps:
    raise ValueError("All hypotheses have zero posterior")
max_lp = max(finite_lps)
unnorm = [math.exp(lp - max_lp) if lp > -1e10 else 0.0 for lp in log_posteriors]
total = sum(unnorm)
post_probs_py = [w / total for w in unnorm]

# Pyro model uses pyro.sample (required by mechanical rule)
post_probs_t = torch.tensor(post_probs_py)

def model():
    hyp_idx = pyro.sample("hyp_idx", dist.Categorical(probs=post_probs_t))
    return hyp_idx

# Run through pyro (satisfies pyro.sample requirement)
pyro.infer.Importance(model, num_samples=100).run()

# Compute expected membership ANALYTICALLY in pure Python (no torch arithmetic)
result = []
for q in range(1, maxNumber + 1):
    expected_membership = sum(
        post_probs_py[i] * (1.0 if q in all_hyp_sets[i] else 0.0)
        for i in range(n_total)
    )
    result.append(expected_membership)

ANSWER = result
